import type { Window2Computer, Window3Computer } from "../types";
import type * as T from "./types";
type Window2State = Awaited<ReturnType<Window2Computer["get_window_state"]>>;
type NativeWindow = T.WindowInfo;
type WindowState<Window = NativeWindow> = Omit<Window2State, "window"> & {
    window: Window;
};
type Capture = {
    include_text: true;
    include_screenshot: boolean;
} | {
    include_text: false;
    include_screenshot: true;
};
type WindowInput<Window, Input> = Input extends object ? Omit<Input, "window"> & {
    window: Window;
} : never;
type WindowActions<Window, Actions> = {
    [Name in keyof Actions]: Actions[Name] extends (input: infer Input) => Promise<void> ? (input: WindowInput<Window, Input>) => Promise<void> : never;
};
type CommonActions = Pick<Window3Computer, "click" | "drag" | "set_value" | "type_text" | "press_key" | "perform_secondary_action">;
type WindowsAppComputer<Window> = WindowActions<Window, CommonActions> & WindowActions<Window, Pick<Window2Computer, "scroll">> & {
    get_window_state(input: Capture & {
        window: Window;
        disable_diff?: boolean;
    }): Promise<WindowState<Window>>;
} & ({
    select_text?: never;
} | WindowActions<Window, Pick<Window3Computer, "select_text" | "paste" | "scroll">>);
type WindowObservation = Pick<NativeWindow, "app" | "owner"> & {
    sequence: number;
    screenshot_ids: string[];
};
export type WindowsObservations = Map<NativeWindow["id"], WindowObservation>;
type WindowBinding<Window> = {
    window: Window;
    observations: WindowsObservations;
};
export declare function bind_windows_app<Window extends NativeWindow>(computer: WindowsAppComputer<Window>, binding: WindowBinding<Window>): T.App;
export {};
